"""Persistent key-value store backed by a single JSON document file (Approach A).

The entire store is one JSON object mapping namespace names to objects that map
keys to values::

    {"default": {"a": "1"}, "other": {"a": "2"}}

On open, the file is loaded into memory (an empty file, or a missing one, is treated
as an empty store). Every mutation rewrites the file in place, so reads never touch
disk after open and the on-disk state always reflects the last completed write. No
temp files, journals, or side directories are ever created next to the data file.

Files written before namespaces existed were a flat ``{key: value}`` object; such a
file is transparently migrated into the ``"default"`` namespace on load.

Namespaces are never stored empty: deleting the last key in a namespace removes the
namespace from the document, so ``namespaces()`` is simply the set of top-level keys.
"""

from __future__ import annotations

import json
import os

DEFAULT_NS = "default"


class Store:
    """A tiny persistent, namespaced string -> string map living in one JSON file."""

    def __init__(self, path: str) -> None:
        self._path = path
        self._closed = False
        self._data: dict[str, dict[str, str]] = self._load()
        if not os.path.exists(self._path):
            # Spec: the data file is created if missing.
            self._flush()

    # ------------------------------------------------------------------ I/O

    def _load(self) -> dict[str, dict[str, str]]:
        try:
            with open(self._path, "r", encoding="utf-8") as fh:
                raw = fh.read()
        except FileNotFoundError:
            return {}
        if not raw.strip():
            return {}
        data = json.loads(raw)
        if not isinstance(data, dict):
            raise ValueError(f"{self._path}: expected a JSON object at top level")
        if not data:
            return {}

        # Legacy (pre-namespace) layout: a flat {key: value} object with string
        # values. Migrate it into the default namespace.
        if all(isinstance(v, str) for v in data.values()):
            if not all(isinstance(k, str) for k in data):
                raise ValueError(f"{self._path}: keys must be strings")
            return {DEFAULT_NS: dict(data)}

        for ns, entries in data.items():
            if not isinstance(ns, str) or not isinstance(entries, dict):
                raise ValueError(
                    f"{self._path}: expected namespace {ns!r} to map to a JSON object"
                )
            for k, v in entries.items():
                if not isinstance(k, str) or not isinstance(v, str):
                    raise ValueError(
                        f"{self._path}: keys and values in namespace {ns!r} must be strings"
                    )
        # Drop any empty namespaces so the in-memory invariant holds.
        return {ns: dict(entries) for ns, entries in data.items() if entries}

    def _flush(self) -> None:
        # Rewrite the single data file in place. ensure_ascii=False keeps arbitrary
        # Unicode human-readable; sort_keys makes the file deterministic.
        with open(self._path, "w", encoding="utf-8") as fh:
            json.dump(self._data, fh, ensure_ascii=False, sort_keys=True, indent=2)
            fh.write("\n")
            fh.flush()
            os.fsync(fh.fileno())

    def _check_open(self) -> None:
        if self._closed:
            raise ValueError("Store is closed")

    @staticmethod
    def _check_ns(ns: str) -> None:
        if not isinstance(ns, str):
            raise TypeError("ns must be str")

    # --------------------------------------------------------------- public

    def set(self, key: str, value: str, ns: str = DEFAULT_NS) -> None:
        self._check_open()
        self._check_ns(ns)
        if not isinstance(key, str) or not isinstance(value, str):
            raise TypeError("key and value must be str")
        self._data.setdefault(ns, {})[key] = value
        self._flush()

    def get(self, key: str, ns: str = DEFAULT_NS) -> str | None:
        self._check_open()
        self._check_ns(ns)
        return self._data.get(ns, {}).get(key)

    def delete(self, key: str, ns: str = DEFAULT_NS) -> bool:
        self._check_open()
        self._check_ns(ns)
        entries = self._data.get(ns)
        if entries is None or key not in entries:
            return False
        del entries[key]
        if not entries:
            del self._data[ns]
        self._flush()
        return True

    def keys(self, ns: str = DEFAULT_NS) -> list[str]:
        self._check_open()
        self._check_ns(ns)
        return sorted(self._data.get(ns, {}))

    def count(self, ns: str = DEFAULT_NS) -> int:
        self._check_open()
        self._check_ns(ns)
        return len(self._data.get(ns, {}))

    def namespaces(self) -> list[str]:
        """Sorted names of namespaces that currently contain at least one key."""
        self._check_open()
        return sorted(self._data)

    def close(self) -> None:
        if self._closed:
            return
        self._flush()
        self._closed = True

    # ---------------------------------------------------------- conveniences

    def __enter__(self) -> "Store":
        return self

    def __exit__(self, *exc: object) -> None:
        self.close()

    def __repr__(self) -> str:
        if self._closed:
            state = "closed"
        else:
            n = sum(len(e) for e in self._data.values())
            state = f"{n} keys in {len(self._data)} namespaces"
        return f"Store({self._path!r}, {state})"
